using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows.Media.Media3D;
namespace GearLab {
 public sealed class TrainStage {
  public string Id{get;set;}public string Name{get;set;}public string Parent{get;set;}public string SecondParent{get;set;}public Parameters Parameters{get;set;}public double PowerShare{get;set;}public double SecondPowerShare{get;set;}public double Gap{get;set;}
  public TrainStage(){Id=Guid.NewGuid().ToString("N");Name="Ступень";Parameters=Engine.Starter(1);PowerShare=1;SecondPowerShare=1;Gap=8;}
 }
 public sealed class TransmissionTrain {
  public int FormatVersion{get;set;}public string Name{get;set;}public double InputRpm{get;set;}public double InputTorque{get;set;}public List<TrainStage> Stages{get;set;}
  public TransmissionTrain(){FormatVersion=1;Name="Многоступенчатый редуктор";InputRpm=300;InputTorque=.35;Stages=new List<TrainStage>();}
  public static TransmissionTrain Example(){var t=new TransmissionTrain();var belt=new TrainStage{Name="Ремень 2:1",Parameters=Engine.Starter(2)};belt.Parameters.Ratio=2;Engine.FitOverall(belt.Parameters);t.Stages.Add(belt);var cycle=new TrainStage{Name="Циклоидальная 20:1",Parent=belt.Id,Parameters=Engine.Starter(0)};cycle.Parameters.Ratio=20;cycle.Parameters.RingOutput=false;Engine.FitOverall(cycle.Parameters);t.Stages.Add(cycle);return t;}
  public void Save(string path){ReleaseSupport.WriteText(path,CADDocument.Serializer().Serialize(this),new System.Text.UTF8Encoding(true));}
  public static TransmissionTrain Read(string path){if(new FileInfo(path).Length>2*1024*1024)throw new Exception("Проект ступеней слишком большой.");var t=CADDocument.Serializer().Deserialize<TransmissionTrain>(File.ReadAllText(path));var s=TrainSolver.Solve(t,false);if(!s.Valid)throw new Exception(string.Join("; ",s.Errors));return t;}
 }
 public sealed class TrainState {public string Id,Name;public double InputRpm,InputTorque,OutputRpm,OutputTorque,OutputForce,LinearSpeed,InputGain,OutputGain,Efficiency,OutputPower;public Result Result;public Matrix3D Frame=Matrix3D.Identity,OutputFrame=Matrix3D.Identity;}
 public sealed class TrainSolution {public List<string> Errors=new List<string>(),Notes=new List<string>();public Dictionary<string,TrainState> States=new Dictionary<string,TrainState>();public Result Scene=new Result{P=new Parameters()};public double Mass;public bool Valid{get{return Errors.Count==0;}}}
 public sealed class TrainMotion {public PartMotion Source;public Matrix3D Frame,Inverse;public double Gain;public Matrix3D At(double phase,double explode){var m=Inverse*Source.At(phase*Gain,0)*Frame;m.Translate(new Vector3D(0,0,explode));return m;}}
 public static class TrainSolver {
  public static double Gain(Result r){if(r.Engineering!=null)return r.Engineering.SpeedGain;if(r.P.Kind==4)return -1/r.Actual;if(r.P.Kind==0)return (r.P.RingOutput?1:-1)/r.Actual;return (r.P.Kind==1?-1:1)/r.Actual;}
  public static TrainSolution Solve(TransmissionTrain train,bool geometry=true){var s=new TrainSolution();s.Scene.Model=new CadAssembly();try{
   if(train==null||train.FormatVersion!=1||train.Stages==null||train.Stages.Count<1||train.Stages.Count>32)throw new Exception("Граф должен содержать 1–32 ступени версии 1.");if(!MechanismCad.Finite(train.InputRpm)||!MechanismCad.Finite(train.InputTorque)||train.InputTorque<0||Math.Abs(train.InputRpm)>100000)throw new Exception("Проверьте параметры двигателя.");if(train.Stages.Any(n=>n==null||string.IsNullOrWhiteSpace(n.Id)||n.Parameters==null)||train.Stages.Select(n=>n.Id).Distinct().Count()!=train.Stages.Count)throw new Exception("Узлы графа должны иметь уникальные идентификаторы.");var ids=new HashSet<string>(train.Stages.Select(x=>x.Id));foreach(var n in train.Stages){if(n.Parent!=null&&!ids.Contains(n.Parent)||n.SecondParent!=null&&!ids.Contains(n.SecondParent))throw new Exception("Ссылка на отсутствующую ступень: "+n.Name);if(n.PowerShare<=0||n.PowerShare>1||n.SecondPowerShare<=0||n.SecondPowerShare>1||n.Gap<1||n.Gap>200)throw new Exception("Доля мощности (0;1], расстояние 1–200 мм.");if(n.SecondParent!=null&&(n.Parameters.Kind!=8||n.Parameters.FixedMember!=3))throw new Exception("Два входа разрешены только у дифференциала со схемой 3.");if(n.Parameters.Kind==8&&n.Parameters.FixedMember==3&&n.SecondParent==null)throw new Exception("Для двухвходового дифференциала задайте второй источник.");}
   foreach(string source in new[]{"MOTOR"}.Concat(ids)){double share=train.Stages.Where(n=>(n.Parent??"MOTOR")==source).Sum(n=>n.PowerShare)+train.Stages.Where(n=>n.SecondParent==source).Sum(n=>n.SecondPowerShare);if(share>1+1e-9)throw new Exception("Сумма долей мощности на разветвлении "+source+" больше 1.");}
   var pending=train.Stages.ToList();int index=0;while(pending.Count>0){var node=pending.FirstOrDefault(n=>(n.Parent==null||s.States.ContainsKey(n.Parent))&&(n.SecondParent==null||s.States.ContainsKey(n.SecondParent)));if(node==null)throw new Exception("Цикл в кинематическом графе. Замкнутый контур требует отдельного решения ограничений.");pending.Remove(node);var parent=node.Parent==null?null:s.States[node.Parent];if(parent!=null&&parent.Result.Engineering!=null&&parent.Result.Engineering.Linear)throw new Exception("После рейки нужен отдельный линейный механизм; вращательный вход к ней не подключается.");double rpm=parent==null?train.InputRpm:parent.OutputRpm,torque=(parent==null?train.InputTorque:parent.OutputTorque)*node.PowerShare,gain=parent==null?1:parent.OutputGain;var p=Engine.Clone(node.Parameters);p.InputRpm=p.Kind<5?Math.Max(.1,Math.Abs(rpm)):rpm;p.InputTorque=torque;TrainState second=null;if(node.SecondParent!=null){second=s.States[node.SecondParent];if(second.Result.Engineering!=null&&second.Result.Engineering.Linear)throw new Exception("Второй вход дифференциала должен вращаться.");p.SecondInputRpm=second.OutputRpm;}
    var r=Engine.Calculate(p);if(!r.Valid)throw new Exception(node.Name+": "+string.Join("; ",r.Errors));double eta=r.Engineering==null?p.Efficiency:r.Engineering.Efficiency,outRpm=r.Engineering==null?rpm*Gain(r):r.Engineering.OutputRpm,outTorque=r.Engineering==null?torque*r.Actual*eta:r.Engineering.OutputTorque;
    if(second!=null){double k=(double)r.Z2*p.PlanetTeeth/(r.Z1*p.SecondPlanetTeeth),t2=second.OutputTorque*node.SecondPowerShare;if(Math.Abs(t2-k*torque)>Math.Max(1e-6,.001*Math.Abs(t2)))throw new Exception(node.Name+": входные моменты не удовлетворяют идеальному балансу Уиллиса Tr=k·Ts. Измените доли мощности/нагрузки.");double power1=torque*Math.Abs(rpm)*Math.PI/30,power2=t2*Math.Abs(p.SecondInputRpm)*Math.PI/30;if(rpm*p.SecondInputRpm<0||Math.Abs(outRpm)<1e-8)throw new Exception("Циркулирующая мощность/неподвижный выход требуют специальной модели потерь.");outTorque=(power1+power2)*eta/(Math.Abs(outRpm)*Math.PI/30);}
    var state=new TrainState{Id=node.Id,Name=node.Name,InputRpm=rpm,InputTorque=torque,OutputRpm=outRpm,OutputTorque=outTorque,InputGain=gain,OutputGain=second==null?gain*Gain(r):train.InputRpm==0?0:outRpm/train.InputRpm,Efficiency=eta,OutputPower=second==null?torque*Math.Abs(rpm)*Math.PI/30*eta:(torque*Math.Abs(rpm)+second.OutputTorque*node.SecondPowerShare*Math.Abs(second.OutputRpm))*Math.PI/30*eta,Result=r};if(r.Engineering!=null&&r.Engineering.Linear){state.OutputForce=r.Engineering.OutputForce;state.LinearSpeed=r.Engineering.LinearSpeed;state.OutputTorque=0;}
    s.States[node.Id]=state;if(!geometry)continue;r.Model=CadBuilder.Build(r);if(!r.Model.Valid)throw new Exception(node.Name+": "+string.Join("; ",r.Model.Errors));Matrix3D frame=Matrix3D.Identity;if(parent!=null){frame=r.InputFrame;if(!frame.HasInverse)throw new Exception("Вырожденный входной интерфейс.");frame.Invert();frame*=RobotMath.Translation(0,0,node.Gap)*parent.OutputFrame;}else if(index>0)frame=RobotMath.Translation(index*220,0,0);state.Frame=frame;state.OutputFrame=r.OutputFrame*frame;if(parent!=null){double d1=parent.Result.P.OutputShaft,d2=p.Shaft,outer=Math.Max(d1,d2)/2+3;var coupling=new CadPart(node.Id+"_COUPLING","Муфта между ступенями · без шпоночного соединения","shaft",TransmissionGeometry.Steel){Placement=parent.OutputFrame};coupling.Sections.Add(new CadSection(-4,node.Gap/2,CadLoop.Round(0,0,outer),new[]{CadLoop.Round(0,0,d1/2)}));coupling.Sections.Add(new CadSection(node.Gap/2,node.Gap+4,CadLoop.Round(0,0,outer),new[]{CadLoop.Round(0,0,d2/2)}));s.Scene.Model.Parts.Add(coupling);var invCoupling=parent.OutputFrame;invCoupling.Invert();s.Scene.TrainMotions[coupling.Id]=new TrainMotion{Source=new PartMotion{Kind="input",Result=new Result{P=new Parameters()}},Frame=parent.OutputFrame,Inverse=invCoupling,Gain=gain};s.Mass+=coupling.Volume()*1e-9*7850;}foreach(var source in r.Model.Parts){if(parent!=null&&source.Reference)continue;var q=new CadPart(node.Id+"_"+source.Id,node.Name+" · "+source.Label,source.Role,source.Color){Reference=source.Reference,SectionUnion=source.SectionUnion,Analytic=source.Analytic,BearingSource=source.BearingSource,BearingElement=source.BearingElement,BearingPitch=source.BearingPitch,BearingBall=source.BearingBall,Loft=source.Loft,MeshOverride=source.MeshOverride,NativeStep=source.NativeStep,NativeVolume=source.NativeVolume,NativeCentre=source.NativeCentre,Placement=source.Placement*frame};q.Sections.AddRange(source.Sections);s.Scene.Model.Parts.Add(q);var inv=frame;inv.Invert();s.Scene.TrainMotions[q.Id]=new TrainMotion{Source=PartMotion.Bind(r,source),Frame=frame,Inverse=inv,Gain=r.Engineering!=null&&r.Engineering.MultiInput?(Math.Abs(train.InputRpm)<1e-12?0:TransmissionSizing.MotionRpm(p)/train.InputRpm):gain};s.Mass+=q.Volume()*1e-9*(q.Role=="housing"?1250:7850);}
    index++;
   }
   if(geometry){s.Scene.Width=s.Scene.Model.Bounds()[1]-s.Scene.Model.Bounds()[0];s.Scene.Height=s.Scene.Model.Bounds()[3]-s.Scene.Model.Bounds()[2];s.Scene.Depth=s.Scene.Model.Bounds()[5]-s.Scene.Model.Bounds()[4];s.Scene.Train=train;s.Notes.Add("Масса: материалы по ролям (корпус 1250, остальные 7850 кг/м³), не паспортные массы. Монтаж — стыковка интерфейсов; внешний габарит пересечений проверяется отдельно. Муфты/адаптеры требуют проверки.");}
  }catch(Exception ex){s.Errors.Add(ex.Message);s.Scene.Error(ex.Message);s.Scene.Model.Errors.Add(ex.Message);}return s;}
 }
}
